mapper.select:
select tr.id, tr.org_id as orgId, tr.type as firstVisit, tr.patient_id as patientId, tr.appointment_id as appointmentId, tr.registered_id as registeredId, tr.dentist_id as treatDentistId, tr.status as treatmentStatus, DATE_FORMAT(tr.treat_start_time, '%Y-%m-%d') as treatDate, DATE_FORMAT(tr.treat_start_time, '%H:%i') as treatStartTime, DATE_FORMAT(tr.treat_end_time, '%H:%i') as treatEndTime, tr.medical_record_completed as medicalRecordCompleted from treatment_record tr
and tr.id = #{queryForm.id}
and tr.org_id = #{queryForm.orgId}
and DATE_FORMAT(tr.treat_start_time, '%Y-%m-%d') = DATE_FORMAT(#{queryForm.currentDate}, '%Y-%m-%d')
and tr.status in
#{item}
and tr.dentist_id = #{queryForm.dentistId}
and tr.inservice = #{queryForm.inservice}
order by tr.id desc

SELECT tr.id AS treatmentRecordId, tr.org_id AS orgId, DATE_FORMAT( tr.treat_start_time, '%Y-%m-%d' ) AS treatmentDate, tr.dentist_id AS dentistId, tr.type AS firstVisit, tr.`status` AS treatmentStatus, tr.appointment_id AS appointmentId, tr.registered_id AS registeredId, ord.id AS orderRecordId, ord.total_amount AS originalPrice, br.id AS billRecordId, br.actual_receivable_amount AS actualReceivableAmount, br.debt_amount AS debtAmount FROM treatment_record tr LEFT JOIN ( SELECT ord.treatment_record_id, ord.id, ord.total_amount FROM order_record ord WHERE ord.inservice = 1 ) ord ON tr.id = ord.treatment_record_id LEFT JOIN ( SELECT br.treatment_record_id, br.id, br.actual_receivable_amount, br.debt_amount FROM bill_record br WHERE br.inservice = 1 ) br ON tr.id = br.treatment_record_id
and tr.patient_id = #{queryForm.patientId}
and DATE_FORMAT(tr.treat_start_time,'%Y-%m-%d') >= #{queryForm.startDate}
and DATE_FORMAT(tr.treat_start_time,'%Y-%m-%d') <= #{queryForm.endDate}
and tr.org_id in
#{item}
and tr.status in
#{item}
ORDER BY tr.treat_start_time DESC

select tr.*,r.assistant_id as regAssistantId, date_format(a.treat_start_time,'%Y-%m-%d') as last_treatment_date from treatment_record tr left join treatment_record a on a.patient_id = tr.patient_id left join registered r on r.id = tr.registered_id where tr.id in
#{item}
order by tr.treat_start_time ,a.treat_start_time desc

SELECT DATE_FORMAT(a.crt_time,'%Y-%m-%d') as currentDate, COUNT(a.id) as `count` FROM( SELECT tr.id, DATE_FORMAT(tr.treat_start_time,'%Y-%m-%d') as crt_time FROM `treatment_record` tr
and tr.dentist_id = #{dentistId}
and date_format(tr.treat_start_time,'%Y-%m-%d') BETWEEN date_format(#{startDate},'%Y-%m-%d') AND date_format(#{endDate},'%Y-%m-%d')
and org_id = #{orgId}
) a GROUP BY a.crt_time

SELECT
COUNT( DISTINCT tr.patient_id ) AS firstTreatPerNumCompleted
FROM
treatment_record tr

    AND tr.type = 0
    AND tr.treat_end_time IS NOT NULL

        AND DATE_FORMAT(tr.treat_start_time, '%Y-%m') = #{query.businessDate}


        AND DATE_FORMAT(tr.treat_start_time, '%Y') = #{query.businessDate}


        AND tr.org_id IN

            #{item}

SELECT
COUNT( tr.id ) AS firstTreatPerNumCompleted
FROM
treatment_record tr

    AND tr.treat_end_time IS NOT NULL

        AND DATE_FORMAT(tr.treat_start_time, '%Y-%m') = #{query.businessDate}


        AND DATE_FORMAT(tr.treat_start_time, '%Y') = #{query.businessDate}


        AND tr.org_id IN

            #{item}

select count(tr.id) as acount
from treatment_record tr


        and date_format(tr.treat_start_time, '%Y-%m-%d') = date_format(#{queryForm.currentDate}, '%Y-%m-%d')


        and tr.org_id = #{queryForm.orgId}


        and tr.inservice = #{queryForm.inservice}


        and tr.dentist_id = #{queryForm.dentistId}


        and tr.status in

            #{status}

SELECT
COUNT( DISTINCT tr.patient_id ) AS firstTreatPerNumCompleted
FROM
treatment_record tr

    AND tr.type = 0
    AND tr.treat_end_time IS NOT NULL

        AND DATE_FORMAT(tr.treat_start_time, '%Y-%m') >= #{query.startDate}


        AND DATE_FORMAT(tr.treat_start_time, '%%Y-%m') <= #{query.endDate}


        AND tr.org_id = #{query.orgId}

SELECT sum( waitingForTreat ) waitingForTreat, sum( treatReceiving ) treatReceiving, sum( treatCompleted ) treatCompleted, sum( checkedOut ) checkedOut FROM ( SELECT COUNT( r.id ) AS waitingForTreat, 0 AS treatReceiving, 0 AS treatCompleted, 0 AS checkedOut FROM registered r
and r.`status` = 0 and r.inservice = 1
and date_format(r.crt_time, '%Y-%m-%d') = date_format(#{queryForm.queryDate},'%Y-%m-%d')
and r.org_id = #{queryForm.orgId}
and r.dentist_id = #{queryForm.dentistId}
UNION ALL SELECT 0 AS waitingForTreat, COUNT( IF ( tr.`status` = 0 OR tr.`status` = 1, 1, NULL ) ) AS treatReceiving, COUNT( IF ( tr.`status` = 2, 1, NULL ) ) AS treatCompleted, COUNT( IF ( tr.`status` = 3, 1, NULL ) ) AS checkedOut FROM treatment_record tr
and tr.inservice = 1
and date_format(tr.treat_start_time, '%Y-%m-%d') = date_format(#{queryForm.queryDate}, '%Y-%m-%d')
and tr.org_id = #{queryForm.orgId}
and tr.dentist_id = #{queryForm.dentistId}
) t
